examples.code:
SELECT httpserve_start('127.0.0.1', 9999, '');

-- Without a credential, other interfaces are refused (DuckDB 2.0 build):
--   SELECT httpserve_start('0.0.0.0', 9999, '');
--   Permission Error: httpserve_start: refusing to serve 0.0.0.0 without authentication ...

SET httpserver_tls_cert = '/etc/duckdb/server.crt';
SET httpserver_tls_key = '/etc/duckdb/server.key';
SELECT httpserve_start('0.0.0.0', 9443, 'shared-api-key');
-- 'HTTPS server started on 0.0.0.0:9443'
